function U.fmt(Db)
Db=tonumber(Db)or 0
if Db>=1e6 then
return string.format(sAd[1721],Db/1e6)
end
if Db>=1e4 then
return string.format(sAd[1722],Db/1e3)
end
return tostring(math.floor(Db+0.5))
end
function U.clamp(Eb,Fb,Gb)
return math.max(Fb,math.min(Gb,Eb))
end
function U.count(Hb)
local Ib=0
for Jb in pairs(Hb or{})do
Ib=Ib+1
end
return Ib
end
function U.list(Kb)
