for op,pp in pairs((mp and mp.inventory and mp.inventory.unique_items)or{})do
local qp=type(pp)==sAd[1723]and N.Items[pp.item_id]
if type(qp)==sAd[1723]and qp.item_group==sAd[1971]then
local rp={uuid=pp.uuid or op,id=pp.item_id,tier=tonumber(qp.tier)or 0,rolls={}}
local tp=type(pp._unique_item_data)==sAd[1723]and type(pp._unique_item_data._unique_charm_data)==sAd[1723]and pp._unique_item_data._unique_charm_data._d
for up,vp in pairs(type(tp)==sAd[1723]and tp or{})do
if type(vp)==sAd[1723]and vp._t then
rp.rolls[tostring(vp._t)]=(rp.rolls[tostring(vp._t)]or 0)+(tonumber(vp._d)or 0)
end
end
table.insert(np,rp)
end
end
return np
