end
function kb.charmScore(Bp,Cp)
local Dp=(Cp and tonumber(Cp.p))or 0.5
local Ep,Fp,Gp=Bp.rolls.unit_damage or 0,Bp.rolls.reward_mul or 0,0
for Hp,Ip in pairs(Bp.rolls)do
if Hp~=sAd[1972]and Hp~=sAd[1973]then
Gp=Gp+Ip
end
end
if Dp>=0.92 then
return Fp*3+Ep+Gp*0.5
end
return Ep*3+Fp+Gp*0.5
end
function kb.charmWords(Jp)
local Kp={}
for Lp,Mp in pairs(Jp.rolls)do
table.insert(Kp,string.format(sAd[1974],Lp==sAd[1972]and sAd[1886]or(Lp==sAd[1973]and sAd[1975]or Lp),math.floor(Mp*100+0.5)))
end
table.sort(Kp)
return string.format(sAd[1976],Jp.tier,#Kp>0 and table.concat(Kp,sAd[1834])or sAd[1977])
end
function kb.charmDmg(Np)
if type(Np)~=sAd[1723]or not(kb.is(Np.id)or Np.portal_group==sAd[1978]or tostring(Np.id):find(sAd[1979],1,true))then
return 0
end
local Op,Pp=kb.charmOn(),0
for Qp,Rp in ipairs(kb.charms())do
local Sp=Rp.rolls.unit_damage or 0
if Op and Rp.uuid==Op then
return Sp
end
if O.smartCharm and Sp>Pp then
Pp=Sp
end
end
return Op and 0 or Pp
end
function kb.charmWant(Tp)
if not O.smartCharm or not kb.charmApplies(Tp)then
return nil
end
P.charm=type(P.charm)==sAd[1723]and P.charm or{}
if os.time()-(tonumber(P.charm.failAt)or 0)<1800 then
return nil
end
local Vp,Wp
for Xp,Yp in ipairs(kb.charms())do
local Zp=kb.charmScore(Yp,Tp)
if not Wp or Zp>Wp then
Vp,Wp=Yp,Zp
end
end
if not Vp then
return nil
end
local _p=kb.charmOn()or(F.where==sAd[1794]and P.charm.uuid)or nil
if _p==Vp.uuid then
return nil
end
return Vp,_p
end
function kb.charmTick(aq)
local bq,cq=kb.charmWant(aq)
if not bq then
return
end
cq=kb.charmOn()
if cq then
F.request(sAd[1980],sAd[1981],cq)
task.wait(1)
end
