local dq=U.now()
while U.now()-dq<4 and kb.charmOn()~=bq.uuid do
task.wait(0.5)
end
if kb.charmOn()==bq.uuid then
P.charm.uuid,P.charm.at,P.charm.failAt=bq.uuid,os.time(),nil
F.saveSoon()
F.log(1,sAd[1983],string.format(sAd[1984],kb.charmWords(bq),tostring(aq.label),math.floor((tonumber(aq.p)or 0)*100+0.5),(tonumber(aq.p)or 0)>=0.92 and sAd[1975]or sAd[1886]))
else
P.charm.failAt=os.time()
F.saveSoon()
F.log(1,sAd[1983],string.format(sAd[1985],kb.charmWords(bq)))
end
end
function kb.weatherStrength(eq)
local fq=kb.fx(eq)
local gq=fq.dmg/fq.cd/fq.hp/fq.speed*(1+(fq.range-1)/2)
for hq,iq in pairs(fq.kinds)do
gq=gq*(1+bb.rogueShare(hq)*iq)
end
if fq.ice>0 then
local jq=bb.rogueShare(sAd[1858])
gq=gq*(jq+(1-jq)/(1-fq.ice+fq.ice/fb.modFactor(sAd[1986])))
end
if fq.fly>0 then
gq=gq*(1-fq.fly*0.5)
end
if fq.noCC then
gq=gq*0.95
end
if fq.shroud then
gq=gq*0.9
end
if fq.zap then
gq=gq*0.85
end
return gq/kb.weatherK(eq)
end
kb.WEATHER_K_MIN,kb.WEATHER_K_MAX,kb.WEATHER_K_RUNS=0.5,4,10
function kb.weatherK(kq)
local lq=kq and type(P.hunt)==sAd[1723]and type(P.hunt.wk)==sAd[1723]and P.hunt.wk[tostring(kq)]or nil
return type(lq)==sAd[1723]and tonumber(lq.k)or 1
end
function kb.weatherLearn()
if bb.withOthers or#game:GetService(sAd[627]):GetPlayers()>1 then
return
end
local mq=bb.huntWeather or kb.weatherNow()
local nq,oq=bb.pred,bb.calRun
if not mq or type(nq)~=sAd[1723]or type(oq)~=sAd[1723]then
return
end
local function pq(qq,rq)
return type(qq)==sAd[1723]and tonumber(qq[rq]or qq[tostring(rq)])or nil
end
local sq={}
for tq=2,bb.wave()do
local uq,vq=pq(oq.alive,tq),pq(nq.aliveAt,tq)
if uq and vq and uq>0 and vq>0 then
table.insert(sq,uq/vq)
end
end
if#sq<3 then
return
end
table.sort(sq)
local wq=sq[math.ceil(#sq/2)]
P.hunt.wk=type(P.hunt.wk)==sAd[1723]and P.hunt.wk or{}
local xq=P.hunt.wk[tostring(mq)]
local yq=math.min(kb.WEATHER_K_RUNS-1,type(xq)==sAd[1723]and tonumber(xq.n)or 0)
local zq=kb.weatherK(mq)
local Aq=math.max(1,yq)
local Bq=math.exp((Aq*math.log(zq)+math.log(zq*wq))/(Aq+1))
Bq=U.clamp(Bq,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(mq),old=xq}
P.hunt.wk[tostring(mq)]={k=Bq,n=(type(xq)==sAd[1723]and tonumber(xq.n)or 0)+1,at=os.time()}
F.log(1,sAd[1987],string.format(sAd[1988],tostring(mq),wq,tostring(mq),Bq,zq,P.hunt.wk[tostring(mq)].n))
end
function kb.cardGems(Cq,Dq)
local Eq=0
local Fq=kb.pearlsFrom(Dq+1,50)
for Gq,Hq in pairs(type(Cq.effects)==sAd[1723]and Cq.effects or{})do
if type(Hq)==sAd[1723]then
local Iq=tonumber(Hq.amount)or 0
if Hq.type==sAd[1989]then
Eq=Eq+math.abs(Iq)*Fq*O.pearlValue
elseif Hq.type==sAd[1990]then
local Jq,Kq=pcall(W.rewardValue,Hq.reward)
if Jq then
Eq=Eq+(tonumber(Kq)or 0)
end
elseif Hq.type==sAd[1991]then
Eq=Eq+Iq*kb.STARFALL_GEMS
elseif Hq.type==sAd[1992]then
Eq=Eq+Iq*100
end
end
end
if Cq.option_type==sAd[1993]then
Eq=Eq+kb.HARD_GEMS
end
if Cq.weather then
local Lq=Cq.weather~=kb.weatherNow()
if Lq and Cq.weather==sAd[1937]then
Eq=Eq+kb.starfallRemnants(50-(tonumber(Dq)or 0))*W.remnantGems(sAd[1942])
end
local Mq=kb.board()
if Lq and Mq and Cq.weather~=sAd[1944]and not Mq.weathers[Cq.weather]then
Eq=Eq+(1000+5000*O.pearlValue+50*W.remnantGems(sAd[1942]))/kb.WEATHERS
end
end
return Eq
end
function kb.text()
