function kb.skinPlan()
local ir,jr=N.session(),N.prof()
local kr=N.data(sAd[1888])or{}
local lr=(jr.inventory and jr.inventory.unique_items)or jr.unique_items or{}
local mr,nr={},{kinds={},sell={},wear={},pearls=0,missing={}}
for pr,qr in pairs(lr)do
local rr=type(qr)==sAd[1723]and N.Items[qr.item_id]
if rr and rr.item_group==sAd[1888]and rr._skin_set==kb.SKIN_SET and rr.usage and kr[rr.usage.skin_id]then
local sr=mr[qr.item_id]
if not sr then
sr={id=qr.item_id,name=rr.name,rarity=rr.rarity,skinId=rr.usage.skin_id,skin=kr[rr.usage.skin_id],uuids={}}
mr[qr.item_id]=sr
table.insert(nr.kinds,sr)
end
table.insert(sr.uuids,qr.uuid or pr)
end
end
table.sort(nr.kinds,function(ur,vr)
return ur.name<vr.name
end)
local wr=kb.team()
local xr=ir.profile_data.collection.owned_units
for yr,zr in ipairs(nr.kinds)do
for Ar,Br in pairs(xr)do
if kb.skinFits(Br.unit_id,zr.skin)then
zr.fits=true
break
end
end
local Cr=zr.rarity==sAd[2016]or zr.rarity==sAd[2017]
zr.keep=(zr.fits or Cr)and 1 or 0
for Dr=zr.keep+1,#zr.uuids do
table.insert(nr.sell,{uuid=zr.uuids[Dr],name=zr.name,pearls=kb.SKIN_PRICE[zr.rarity]or 0})
nr.pearls=nr.pearls+(kb.SKIN_PRICE[zr.rarity]or 0)
end
end
for Er,Fr in ipairs(wr)do
local Gr=Fr.skin and Fr.skin._skin_id and kr[Fr.skin._skin_id]
if not(Gr and Gr._skin_set==kb.SKIN_SET)then
for Hr,Ir in pairs(kr)do
if type(Ir)==sAd[1723]and Ir._skin_set==kb.SKIN_SET and kb.skinFits(Fr.unit_id,Ir)then
local Jr=Hr..sAd[2018]
if mr[Jr]then
table.insert(nr.wear,{uuid=mr[Jr].uuids[1],unit=Fr.uuid,unitName=V.name(Fr.unit_id),name=mr[Jr].name})
else
table.insert(nr.missing,{item=Jr,unitName=V.name(Fr.unit_id),name=Ir.name,boost=tonumber(Ir._damage_boost)or 0,drop=kb.SKIN_DROP[Ir._skin_rarity]or 0})
end
end
end
end
end
return nr
end
function kb.starPlan(Kr)
Kr=Kr or kb.skinPlan()
local Lr=N.Items[kb.STAR]or{}
local Mr=tonumber(Lr._mythic_unit_pity)or 400
local Nr=(N.prof().capsule_pity_data or{})[kb.STAR]or{}
local Or=tonumber(Nr.opens_since_mythic_unit)or 0
local Pr={opened=tonumber(Nr.total_opens)or 0,left=math.max(1,Mr-Or),units={}}
local Qr=tonumber(N.cur(sAd[2013]))or 0
Pr.can=math.max(0,math.floor((Qr-(tonumber(O.pearlFloor)or 0))/kb.STAR_COST))
local Rr={}
for Sr,Tr in pairs(N.session().profile_data.collection.owned_units)do
Rr[Tr.unit_id]=true
local Ur=N.Units[Tr.unit_id]
if Ur and Ur.evolved and Ur.evolved.from then
Rr[Ur.evolved.from]=true
end
end
for Vr,Wr in pairs(Lr.usage and Lr.usage.possible_rewards or{})do
local Xr=Wr.unit or Wr.item
if Xr and N.Units[Xr]and N.Units[Xr].rarity==sAd[2017]and not Rr[Xr]then
table.insert(Pr.units,V.name(Xr))
end
end
table.sort(Pr.units)
local Yr={}
if#Kr.missing>0 then
local Zr=Kr.missing[1]
table.insert(Yr,string.format(sAd[2019],Zr.name,Zr.unitName))
end
if#Pr.units>0 then
table.insert(Yr,string.format(sAd[2020],table.concat(Pr.units,sAd[1834])))
end
Pr.why=table.concat(Yr,sAd[2021])
Pr.open= #Yr>0 and math.min(Pr.can,#Pr.units>0 and Pr.left or 100)or 0
return Pr
end
function kb.skinText()
