function kb.skinTick()
if not(O.skinSmart or O.starOpen)or not(P.live.event and kb.is(P.live.event.level))then
return
end
if(F.req.back.skins or 0)>U.now()then
return
end
local vs=N.session()
local function ws(xs,ys,zs)
local As=F.gameSaid(ys)
ab.pickNote.skins=string.format(sAd[2039],xs,tostring(As or zs or sAd[2040]))
F.log(1,sAd[1958],ab.pickNote.skins)
F.backoff(sAd[2041],1800)
end
local Bs=kb.skinPlan()
if O.skinSmart then
local Cs=Bs.wear[1]
if Cs and(F.req.back.skinWear or 0)<=U.now()then
local Ds=jb.slotOf(Cs.unit)
if Ds then
P.str.reequip={uuid=Cs.unit,slot=Ds}
F.saveNow()
F.request(sAd[2042],sAd[2043],Cs.unit)
local Es=U.now()
while U.now()-Es<4 and jb.slotOf(Cs.unit)do
task.wait(0.25)
end
end
local Fs=U.now()
local Gs,Hs=F.request(sAd[2044],sAd[1982],Cs.uuid,{unit_uuid=Cs.unit})
local function Is()
local Js=vs.collection:get_unit_by_uuid(Cs.unit)
return Js and Js.skin~=nil
end
while U.now()-Fs<5 and not Is()do
task.wait(0.25)
end
if Ds then
jb.reequip()
end
if Is()then
F.log(1,sAd[1958],string.format(sAd[2045],Cs.name,Cs.unitName))
ab.pickNote.skins=nil
Bs=kb.skinPlan()
else
local Ks=F.gameSaid(Fs)
ab.pickNote.skins=string.format(sAd[2046],Cs.name,tostring(Ks or Hs or sAd[2040]))
F.log(1,sAd[1958],ab.pickNote.skins)
F.backoff(sAd[2044],1800)
end
end
if#Bs.sell>0 then
local Ls,Ms={},0
for Ns=1,math.min(50,#Bs.sell)do
table.insert(Ls,Bs.sell[Ns].uuid)
Ms=Ms+Bs.sell[Ns].pearls
end
local Os=tonumber(N.cur(sAd[2013]))or 0
local Ps=U.now()
local Qs,Rs=F.request(sAd[2047],sAd[2048],Ls)
