task.wait(0.25)
end
local Ss=(tonumber(N.cur(sAd[2013]))or 0)-Os
if Ss<=0 then
return ws(sAd[2049],Ps,Rs)
end
cb.add(string.format(sAd[2050],#Ls),#Ls,sAd[2041],string.format(sAd[2051],U.fmt(Ss)))
