function jb.relicWorth(KQ,LQ)
local MQ=LQ._unique_item_data and LQ._unique_item_data._unique_relic_data
if not MQ then
return 0
end
local NQ=N.Items[LQ.item_id]or{}
local OQ,PQ=V.types(KQ.unit_id)
if NQ.main_damage_type and NQ.main_damage_type~=sAd[2432]and NQ.main_damage_type~=PQ then
return 0
end
local QQ,RQ=0,0
for SQ,TQ in pairs(MQ._core_damage_type_buffs or{})do
if OQ[TQ.damage_type]then
QQ=QQ+(tonumber(TQ.mul)or 0)+(tonumber(TQ.add_upg)or 0)*0.01+(tonumber(TQ.pen)or 0)*0.001
RQ=RQ+(tonumber(TQ.crit)or 0)
end
end
QQ=QQ+RQ*0.5
local UQ=V.rows(KQ.unit_id)
local VQ=UQ and UQ[UQ.max]
local WQ=(VQ and tonumber(VQ.cd)or 0)*V.mult(KQ,sAd[1887])
for XQ,YQ in pairs(MQ._unique_relic_effects or{})do
local ZQ=type(YQ.params)==sAd[1723]and YQ.params or{}
if YQ.id==sAd[2433]then
local _Q=math.min(1,(tonumber(ZQ.extra_damage)or 0)*WQ/math.max(1,tonumber(ZQ.time_interval)or 40))
local aR=V.DRONES and V.DRONES[KQ.unit_id]
if aR and aR.late and WQ>0 then
local bR=1/WQ
_Q=_Q*bR/(bR+(tonumber(aR.max)or 0)*(tonumber(aR.late.dmg)or 0)*(tonumber(aR.hits)or 1)/math.max(0.1,tonumber(aR.late.cd)or 4))
end
QQ=QQ+_Q
elseif YQ.id==sAd[2434]then
QQ=QQ+(tonumber(ZQ.dmg_buff)or 0)*0.25
elseif YQ.id==sAd[2435]then
QQ=QQ+(tonumber(ZQ.dmg_buff)or 0)*RQ
elseif YQ.id==sAd[2436]then
if OQ.magic then
QQ=0
else
QQ=QQ+(tonumber(ZQ.dmg_buff)or 0)*0.3
end
elseif YQ.id==sAd[2437]then
if OQ.water_damage then
QQ=QQ+0.05
end
end
end
return QQ
end
function jb.relicPlan()
