DR[JR.e.uuid]=LR.it.uuid
GR(HR+1,IR+LR.w+(LR.it.uuid==JR.e.u._equipped_relic and 0.01 or 0))
DR[JR.e.uuid]=nil
ER[LR.it.uuid]=nil
if MR then
FR[LR.it.item_id]=nil
end
end
end
end
GR(1,0)
local NR,OR=0,{}
for PR,QR in ipairs(hR)do
