local function cS(dS)
for eS,fS in pairs(bS)do
if fS._equipped_relic==dS then
return eS,fS
end
end
end
local function gS(hS)
return F.gameSaid(hS)or sAd[2040]
end
local function iS(jS)
local kS,lS=cS(jS)
if not kS then
return true
end
local mS=U.now()
F.request(sAd[2442],sAd[2443],jS)
while U.now()-mS<4 and lS._equipped_relic==jS do
task.wait(0.25)
end
task.wait(1.2)
if lS._equipped_relic==jS then
F.log(1,sAd[2423],string.format(sAd[2444],V.name(lS.unit_id),tostring(V.relicName(lS)),gS(mS)))
F.backoff(sAd[2442],300)
