end
F.log(1,sAd[2423],string.format(sAd[2445],YR,table.concat(ZR,sAd[1953])))
for nS,oS in ipairs(_R)do
local pS=oS.e.u._equipped_relic
if pS and pS~=XR[oS.e.uuid]and not iS(pS)then
return false
end
end
for qS,rS in pairs(XR)do
local sS=cS(rS)
if sS and sS~=qS and not iS(rS)then
return false
end
end
table.sort(_R,function(tS,uS)
return tS.share>uS.share
end)
local vS=0
for wS,xS in ipairs(_R)do
