local zS,AS=0,nil
local BS={}
for CS,DS in ipairs(V.equipped())do
BS[DS.uuid]=true
end
for ES,FS in pairs(bS)do
if FS._equipped_relic then
zS=zS+1
if not BS[ES]and(not AS or not table.find(P.str.core or{},ES))then
AS=FS._equipped_relic
end
end
end
if zS>=jb.MAX_RELICS and AS and not iS(AS)then
return false
end
local HS=U.now()
F.request(sAd[2442],sAd[1982],yS,{unit_uuid=xS.e.uuid})
while U.now()-HS<4 and xS.e.u._equipped_relic~=yS do
task.wait(0.25)
end
task.wait(1.2)
if xS.e.u._equipped_relic~=yS then
F.log(1,sAd[2423],string.format(sAd[2446],(N.Items[(aS.inventory:get_item_by_uuid(yS)or{}).item_id]or{}).name or sAd[2447],V.name(xS.e.id),gS(HS)))
F.backoff(sAd[2442],300)
P.str.relicAt=0
return false
end
vS=vS+1
end
end
W._sigAt=nil
P.str.relicSig=W.teamSig()
P.str.relicTeam=P.str.relicSig
P.str.relicNote=string.format(sAd[2448],YR)
jb.note(string.format(sAd[2449],vS,YR))
return true
end
function jb.foodHeld()
