local NS=N.Items[LS]
if type(NS)==sAd[1723]and type(NS.usage)==sAd[1723]and NS.usage.type==sAd[2450]and(tonumber(MS)or 0)>0 then
table.insert(JS,{id=LS,n=tonumber(MS),xp=tonumber(NS.usage.xp_amount)or 0})
end
end
table.sort(JS,function(OS,PS)
return OS.xp>PS.xp
end)
