_S=_S+bT.n*bT.xp
end
for cT,dT in ipairs(YS)do
local eT=WS.collection:get_unit_by_uuid(dT)
if eT then
local fT,gT=eT.unit_id,V.name(eT.unit_id)
if O.teamXp and _S>0 then
local hT,iT=jb.gainXp(eT,_S)
local jT,kT=jb.gainXp(eT,500000)
local lT=kT>0 and jT/kT*iT or 0
if iT>0 and lT>0 then
local mT=jb.feedPlan(eT)
local nT,oT=jb.level(eT),jb.level({unit_id=fT,xp=(tonumber(eT.xp)or 0)+iT})
table.insert(XS,{kind=sAd[2451],uuid=dT,name=gT,gain=lT,add=iT,planned=mT.planned,items=mT.n,lvl0=nT,lvl1=jb.level({unit_id=fT,xp=(tonumber(eT.xp)or 0)+(mT.planned>0 and mT.planned or iT)}),text=string.format(sAd[2452],gT,U.fmt(iT),oT>nT and string.format(sAd[2453],nT,oT)or string.format(sAd[2454],nT),lT)})
end
end
end
end
table.sort(XS,function(pT,qT)
if pT.gain~=qT.gain then
return pT.gain>qT.gain
end
return pT.text<qT.text
end)
for rT in pairs(V._mult)do
if type(rT)==sAd[634]and rT:sub(1,5)==sAd[2426]then
V._mult[rT]=nil
end
end
P.str.acts,P.str.actsAt={},os.time()
for sT=1,math.min(12,#XS)do
local tT=XS[sT]
table.insert(P.str.acts,{kind=tT.kind,uuid=tT.uuid,name=tT.name,gain=tT.gain,text=tT.text,blocked=tT.blocked,add=tT.add,planned=tT.planned,items=tT.items,lvl0=tT.lvl0,lvl1=tT.lvl1})
