return XS
end
function jb.xpRate()
local uT=N.session()
if not uT then
return 0
end
local vT=0
for wT,xT in ipairs(jb.core())do
local yT=uT.collection:get_unit_by_uuid(xT)
if yT then
local zT,AT=jb.gainXp(yT,500000)
if AT>0 then
vT=math.max(vT,zT/AT)
end
end
end
local BT=vT*(O.strengthValue or 300)
if(tonumber(N.cur(sAd[1788]))or 0)>(O.xpGoldFloor or 100000)then
BT=math.min(BT,(N.GOLD_VALUE or 0.02)/14)
end
return BT
end
function jb.xpGuess(CT)
local ET=CT.level and N.Levels[CT.level]
if not ET then
return 0
end
local FT=math.min(9,tonumber(ET.story_world_rank)or tonumber(CT.rank)or 9)
local GT=tonumber(ET.story_level_rank)or 6
local HT=(CT.kind==sAd[1762]and 1.5 or 1)*(FT>5 and 2 or 1)
local IT=2.1564^(FT-1)*(40+10*GT)/HT
if CT.kind==sAd[1742]then
IT=3*30*2.1564^(FT-1)/HT
end
local JT=FT>=9 and 0.3 or(FT>=7 and 0.5 or 1)
return IT*JT*6
end
function jb.modeBonus(KT)
if not(O.team and O.teamXp)or KT.kind==sAd[1743]or KT.kind==sAd[1740]then
return 0
end
local LT=jb._xpRate and os.time()-(jb._xpRateAt or 0)<300 and jb._xpRate or nil
if not LT then
LT=jb.xpRate()
jb._xpRate,jb._xpRateAt=LT,os.time()
end
if LT<=0 then
return 0
end
local NT=P.modes and P.modes[KT.key]
local OT=tonumber(NT and NT.xp)or jb.xpGuess(KT)
local PT=OT*LT
if PT<1 then
return 0
end
return PT,string.format(sAd[2455],U.fmt(OT),math.floor(PT+0.5))
end
function jb.xpSettle()
local QT=P.lastRun
if not(QT and type(QT.xp0)==sAd[1723]and QT.key)then
return
end
local RT=N.session()
if not RT then
return
end
local TT,UT=0,0
for VT,WT in pairs(QT.xp0)do
local XT=RT.collection:get_unit_by_uuid(VT)
if XT then
TT=TT+math.max(0,(tonumber(XT.xp)or 0)-(tonumber(WT)or 0))
UT=UT+1
end
end
P.lastRun=nil
if UT==0 then
return
end
local YT=W.rec(QT.key)
YT.xp=YT.xp and(YT.xp+(TT-YT.xp)*0.3)or TT
if TT>0 then
F.log(2,jb.LOG,string.format(sAd[2456],QT.key,U.fmt(TT)))
end
F.saveSoon()
end
