function jb.feedPlan(_T)
local aU=V.trait(_T)
local bU=aU==sAd[2457]and 1.5 or 1
local cU=math.max(0,jb.xpFor(_T.unit_id,jb.cap(_T))-(tonumber(_T.xp)or 0))
local dU,eU,fU={},0,0
for gU,hU in ipairs(jb.foodHeld())do
local iU=hU.xp*bU
local jU=math.min(hU.n,math.floor((cU-eU)/math.max(1,iU)))
if jU>0 then
dU[hU.id]=jU
eU=eU+jU*iU
fU=fU+jU
end
end
return{feed=dU,planned=eU,n=fU}
end
function jb.run(kU)
local lU=N.session()
local mU=lU and lU.collection:get_unit_by_uuid(kU.uuid)
if not mU then
return
end
if kU.kind==sAd[2451]then
local nU=jb.feedPlan(mU)
local oU,pU,qU=nU.feed,nU.planned,nU.n
if qU==0 then
P.str.feedNote=kU.name..sAd[2458]
return
end
local rU,sU=tonumber(mU.xp)or 0,jb.level(mU)
local tU,uU=F.request(sAd[2451],sAd[2459],kU.uuid,oU)
local vU=U.now()
while U.now()-vU<4 and(tonumber((lU.collection:get_unit_by_uuid(kU.uuid)or mU).xp)or 0)<=rU do
task.wait(0.25)
end
local wU=lU.collection:get_unit_by_uuid(kU.uuid)or mU
local xU=(tonumber(wU.xp)or 0)-rU
if xU>0 then
local yU=jb.level(wU)
local zU=yU>sU and string.format(sAd[2453],sU,yU)or string.format(sAd[2454],sU)
cb.add(string.format(sAd[2460],qU,kU.name),qU,sAd[2461],string.format(sAd[2462],U.fmt(xU),zU))
jb.note(string.format(sAd[2463],kU.name,qU,U.fmt(xU),zU,math.abs(xU-pU)>pU*0.1 and string.format(sAd[2464],U.fmt(pU))or sAd[648]))
else
jb.note(string.format(sAd[2465],kU.name,tostring(tU and uU or sAd[2040])))
F.backoff(sAd[2451],600)
end
end
end
