function ab.evolveBuyPlan(wW)
if not(O.autoEvolve and wW and wW.pinned and not wW.ready and wW.uuid==O.evolveUnit)then
return nil
end
for xW,yW in ipairs(wW.plans or{})do
if yW.eventShop and(tonumber(yW.cost)or 0)>0 and yW.currency and gb.have(yW.item)<(tonumber(yW.need)or 1)and(tonumber(N.cur(yW.currency))or 0)>=yW.cost then
return yW
end
end
