end
function ab.evolveBuy(zW)
local AW=ab.evolveBuyPlan(zW)
if not AW or F.where~=sAd[1793]then
return false
end
if F.req.back.evobuy and U.now()<F.req.back.evobuy then
return false
end
local BW=(N.Items[AW.item]or{}).name or AW.item
local CW=gb.have(AW.item)
local DW,EW=F.request(sAd[2530],sAd[2057],AW.item,sAd[1740],sAd[2058],sAd[1890])
local FW=U.now()
while U.now()-FW<4 and gb.have(AW.item)<=CW do
task.wait(0.25)
end
if gb.have(AW.item)>CW then
cb.add(BW,AW.cost,tostring(AW.currency),sAd[2531]..V.name(zW.from)..sAd[2532])
if F.notify then
F.notify(sAd[2528],sAd[2364]..BW..sAd[2473]..V.name(zW.from),sAd[2366])
end
pcall(gb.refresh)
return true
end
F.log(1,sAd[2367],string.format(sAd[2533],BW,tostring(DW and EW or sAd[2040])))
F.backoff(sAd[2530],900)
return false
end
function ab.autoEvolve()
