return ab.pickDone(sAd[2534],sAd[2528],sAd[2535],sAd[2536])
end
local HW
for IW,JW in ipairs(P.goals or{})do
if JW.pinned and JW.uuid==O.evolveUnit then
HW=JW
break
end
end
if not HW then
local KW=GW.collection:get_unit_by_uuid(O.evolveUnit)
local LW=N.Units[KW.unit_id]
if not(LW and LW.evolve and LW.evolve.evolve_unit)then
ab.pickDone(sAd[2534],sAd[2528],V.name(KW.unit_id)..sAd[2537],sAd[2536])
