for MW,NW in ipairs(P.goals or{})do
if NW.pinned and NW.uuid==O.evolveUnit then
HW=NW
break
end
end
end
if not HW.ready then
return
end
local OW={}
for PW,QW in ipairs(V.equipped())do
OW[QW.uuid]=true
end
local RW=ab.evoEats(HW,OW)
if RW then
