ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(XW)
local YW=N.session()
local ZW=ab.FUSE_RANK[O.fuseXpRarity]or 2
local _W={[XW.uuid]=true,[O.evolveUnit]=true}
for aX,bX in ipairs(V.equipped())do
_W[bX.uuid]=true
end
for cX,dX in ipairs(P.savedTeam or{})do
_W[dX]=true
end
for eX,fX in ipairs(P.train and P.train.on and P.train.on.base or{})do
_W[fX]=true
end
local gX,hX={},0
for iX,jX in pairs(YW.profile_data.collection.owned_units)do
local kX=N.Units[jX.unit_id]
local lX=kX and ab.FUSE_RANK[kX.rarity]
if lX and lX<=ZW and not _W[iX]then
local mX=YW.collection:get_unit_by_uuid(iX)or jX
if not(jX._locked or mX._locked)and not(jX._equipped_relic or mX._equipped_relic)then
local nX,oX=pcall(N.USC.calculate_xp_gain_from_fuse,XW,{mX},YW)
oX=nX and tonumber(oX)or 0
if oX>0 then
table.insert(gX,{uuid=iX,id=jX.unit_id,xp=oX,rarity=kX.rarity})
hX=hX+oX
end
end
end
end
table.sort(gX,function(pX,qX)
if pX.xp~=qX.xp then
return pX.xp<qX.xp
end
return pX.uuid<qX.uuid
end)
local rX=math.max(0,jb.xpFor(XW.unit_id,jb.cap(XW))-(tonumber(XW.xp)or 0))
local sX,tX={},0
for uX,vX in ipairs(gX)do
if tX>=rX then
break
end
table.insert(sX,vX)
tX=tX+vX.xp
end
return sX,tX,rX,hX
end
