function ab.autoFuseXp()
if not O.autoFuseXp or O.fuseXpUnit==sAd[648]then
return
end
local SX=N.session()
local TX=ab.fuseXpTarget(SX)
if not TX then
return
end
local UX=V.name(TX.unit_id)
local VX,WX,XX=ab.xpFodder(TX)
if XX<=0 then
ab.pickNote.autoFuseXp=nil
return
end
if#VX==0 then
ab.pickNote.autoFuseXp=sAd[2553]
return
end
if os.time()-(tonumber(O.fuseXpOnAt)or 0)<30 then
ab.pickNote.autoFuseXp=sAd[2554]
return
end
ab.pickNote.autoFuseXp=nil
if F.req.back.fuseXp and U.now()<F.req.back.fuseXp then
return
end
ab.fuseBatch=ab.fuseBatch or 50
local YX,ZX,_X=0,0,{}
while F.alive and YX<10 and not P.pauseAll do
if YX>0 then
local aY,bY,cY=ab.xpFodder(SX.collection:get_unit_by_uuid(O.fuseXpUnit)or TX)
VX,XX={},cY
for dY,eY in ipairs(aY)do
if not _X[eY.uuid]then
table.insert(VX,eY)
end
end
if XX<=0 or#VX==0 then
break
end
end
local fY={}
for gY=1,math.min(ab.fuseBatch,#VX)do
table.insert(fY,VX[gY].uuid)
end
local hY=tonumber((SX.collection:get_unit_by_uuid(O.fuseXpUnit)or TX).xp)or 0
local iY=U.now()
local jY,kY=F.request(sAd[2555],sAd[2556],O.fuseXpUnit,fY)
if not jY and(kY==sAd[1796]or kY==sAd[1795])then
if kY==sAd[1795]or ZX>=3 then
break
end
ZX=ZX+1
task.wait(3.5)
continue
end
while U.now()-iY<5 and(tonumber((SX.collection:get_unit_by_uuid(O.fuseXpUnit)or TX).xp)or 0)<=hY do
task.wait(0.1)
end
local lY=tonumber((SX.collection:get_unit_by_uuid(O.fuseXpUnit)or TX).xp)or 0
if lY>hY then
YX=YX+1
for mY,nY in ipairs(fY)do
_X[nY]=true
end
cb.add(string.format(sAd[2557],#fY,UX),#fY,sAd[2558],string.format(sAd[2559],U.fmt(lY-hY)))
F.log(1,sAd[1958],string.format(sAd[2560],#fY,UX,U.fmt(lY-hY),jb.level(SX.collection:get_unit_by_uuid(O.fuseXpUnit)or TX)))
elseif#fY>20 then
ab.fuseBatch=20
F.log(1,sAd[1958],string.format(sAd[2561],#fY,tostring(F.gameSaid(iY)or(jY and kY)or sAd[2040])))
else
local oY=F.gameSaid(iY)
ab.pickNote.autoFuseXp=sAd[2562]..tostring(oY or(jY and kY)or sAd[2040])..sAd[2563]
F.log(1,sAd[1958],sAd[2564]..tostring(oY or(jY and kY)or sAd[2040]))
F.backoff(sAd[2555],1800)
break
end
end
end
