rZ=math.max(rZ,tZ.gain/tZ.cost)
end
end
for uZ,vZ in ipairs(mZ)do
if vZ.train==sAd[2611]or(vZ.train==sAd[2612]and qZ)then
vZ.gain=math.max(vZ.gain,rZ*vZ.cost*1.05)
end
end
end
