function hb.target()
local JZ=N.session()
if not JZ then
return nil
end
local KZ,LZ
local MZ=O.autoEvolve and O.evolveUnit~=sAd[648]and O.evolveUnit or nil
for NZ,OZ in ipairs(P.goals or{})do
local PZ,QZ=nil,0
for RZ,SZ in ipairs(OZ.plans or{})do
if SZ.takedown then
PZ=SZ
else
QZ=QZ+1
end
end
local TZ=PZ and OZ.intoTeam and(OZ.pinned or not OZ.unknown)and(not MZ or OZ.uuid==MZ)and JZ.collection:get_unit_by_uuid(OZ.uuid)
if TZ then
local UZ=tonumber(PZ.what==sAd[2098]and TZ.total_kills or TZ.total_takedowns)or 0
if UZ<PZ.need then
local VZ=(QZ==0 and 1000 or 0)+(tonumber(OZ.tierRank)or 0)*10-NZ*0.01
if not KZ or VZ>LZ then
KZ,LZ={uuid=OZ.uuid,id=OZ.from,to=OZ.to,what=PZ.what,have=UZ,need=PZ.need},VZ
end
end
end
end
return KZ
