function hb.now()
if hb._at and U.now()-hb._at<10 then
return hb._t,hb._base
end
local _Z=(P.train.on and P.train.on.base)or hb.team()
local a_=table.clone(_Z)
table.sort(a_)
hb._t,hb._base,hb._at=hb.target(),table.concat(a_,sAd[2427]),U.now()
return hb._t,hb._base
end
function hb.valueFor(b_)
if not(O.trainTakedowns and O.goals)then
return 0,1
end
local c_=P.trainSim[b_.key]
if not(c_ and c_.ok and os.time()-(c_.at or 0)<6*3600)then
return 0,1
end
local d_,e_=hb.now()
local f_={}
for g_,h_ in ipairs(P.savedTeam or{})do
f_[g_]=h_
end
table.sort(f_)
if not(d_ and c_.uuid==d_.uuid and(c_.base==e_ or c_.base==table.concat(f_,sAd[2427])))or not hb.eligible(b_)then
return 0,1
end
local i_=hb.perRun(b_.key,d_.id)or 0
local j_=math.max(1,d_.need-d_.have)
return O.goalValue*math.min(i_,j_)/j_,c_.slow or 1
end
function hb.scan()
local k_=O.trainTakedowns and O.sim and hb.now()
if not k_ then
return
end
local l_=(P.train.on and P.train.on.base)or hb.team()
for m_,n_ in ipairs(l_)do
if n_==k_.uuid then
return
end
end
local o_,p_=0,0
for q_,r_ in ipairs(W.lastScored or{})do
if o_>=3 or p_>=2 then
break
end
if hb.eligible(r_)then
local s_=P.trainSim[r_.key]
local t_=s_ and s_.uuid==k_.uuid and os.time()-(s_.at or 0)<6*3600
local u_=hb.plan(r_,k_,l_)
if not t_ then
p_=p_+1
end
if u_.ok then
o_=o_+1
end
end
end
local v_=hb.bestInfinite()
if v_ then
hb.plan(v_,k_,l_)
end
end
function hb.bestInfinite()
local w_,x_
for y_,z_ in ipairs(W.lastScored or{})do
if z_.kind==sAd[1742]and hb.eligible(z_)then
local A_,B_=P.train.real[z_.key],z_.rec or W.rec(z_.key)
local C_=(tonumber(B_.timed)or 0)>0 and B_.sec/B_.timed/60 or 0
local D_=(A_ and A_.n>0 and C_>0)and(A_.sum/A_.n)/C_ or 0
if D_<=0 then
D_=db.hiveTrainRate(z_.key)or 0
end
if D_>(x_ or 0)then
w_,x_=z_,D_
