local jeb=jb.score(ieb)
if jeb>0 and(not beb or heb<ceb or(heb==ceb and jeb>deb))then
beb,ceb,deb={uuid=eeb,id=geb,u=ieb},heb,jeb
end
end
end
end
if not beb then
