local pib=(nib.cd>0 and nib.damage/nib.cd or 0)*V.aoe(nib.atk,nib.range)/math.max(0.3,V.aoe(mib.atk,mib.range))
local qib=oib>0 and gib*(pib/oib-1)or(lib or 0)
local rib=hib[iib+2]
if rib and iib+1<hib.max and rib.cd>0 and nib.cd>0 and oib>0 then
local sib=gib*((rib.damage/rib.cd)/oib-1)
local tib=jib+rib.cost*kib
if sib/tib>qib/jib then
qib=qib+(sib/tib*jib-qib)*0.5
end
end
local uib=(nib.range or 0)>(mib.range or 0)and(1+((nib.range-mib.range)/math.max(1,mib.range)))or 1
return math.max(0,qib)*uib
end
function eb.dpsFor(vib,wib)
