local xib={}
for yib,zib in ipairs(vib)do
if not zib.farm and zib.gain>0 then
table.insert(xib,zib)
end
end
table.sort(xib,function(Aib,Bib)
return Aib.gain/Aib.cost>Bib.gain/Bib.cost
end)
local Cib,Dib=0,0
for Eib,Fib in ipairs(xib)do
if wib<=0 then
break
end
Dib=Fib.gain/Fib.cost
local Gib=math.min(1,wib/Fib.cost)
Cib=Cib+Fib.gain*Gib
wib=wib-Fib.cost*Gib
end
return Cib+math.max(0,wib)*Dib*0.7
end
function eb.shieldDps(Hib,Iib,Jib,Kib,Lib,Mib,Nib)
