if type(_ob)==sAd[1723]and tonumber(_ob.spawn_tier_boss)and(Vlb(N.LU.Infinite.infinite_get_boss_unit_chance,_ob,zob)or 0)>0 then
local apb=fb.baseStats(yob,Zob)
if apb then
table.insert(Xob,{k=Zob,hp=apb,tier=tonumber(_ob.spawn_tier_boss)})
Yob=Yob+apb
end
end
end
table.sort(Xob,function(bpb,cpb)
return bpb.tier>cpb.tier
end)
local dpb=type(yob.ld._dungeon)==sAd[1723]and(tonumber(yob.ld._dungeon.depth)or 0)>=20
local epb=Xob[1]
if epb and not dpb then
local fpb=Yob/ #Xob
for gpb,hpb in ipairs(Xob)do
if math.abs(hpb.hp-fpb)<math.abs(epb.hp-fpb)then
epb=hpb
end
end
end
if epb then
local ipb=fb.enemy(yob,epb.k,zob)
if ipb then
ipb.boss=true
table.insert(Bob,ipb)
end
end
elseif zob%yob.bossEvery==0 and not yob.skip[tostring(zob)]then
local jpb=math.max(1,math.min(6,math.floor(zob/yob.bossEvery)))
for kpb,lpb in pairs(yob.configs)do
if type(lpb)==sAd[1723]and tonumber(lpb.spawn_tier_boss)==jpb then
local mpb=fb.enemy(yob,kpb,zob)
if mpb then
mpb.boss=true
table.insert(Bob,mpb)
end
break
end
end
end
if yob.final and tonumber(yob.final.wave)==zob and yob.final.cfg then
local npb=fb.enemy(yob,yob.final.cfg,zob)
if npb then
npb.boss=true
table.insert(Bob,npb)
end
end
end
local opb=yob.fx and yob.fx.starfall
local ppb=opb and yob.cfgById and yob.cfgById.star_golem_1
if ppb and(tonumber(opb.perWave)or 0)>0 then
if zob<=1 then
yob.starAcc=0
end
yob.starAcc=(yob.starAcc or 0)+opb.perWave
while yob.starAcc>=1 do
local qpb=fb.enemy(yob,ppb,zob)
if qpb then
local rpb=tonumber(opb.hpK)or 1
qpb.hp,qpb.max=qpb.hp*rpb,qpb.max*rpb
table.insert(Bob,qpb)
end
yob.starAcc=yob.starAcc-1
end
end
local spb=tonumber(yob.cal and yob.cal.countCal)
if spb and not Aob and math.abs(spb-1)>0.05 and#Bob>0 then
local tpb=math.max(1,math.floor(#Bob*spb+0.5))
local upb= #Bob
if tpb>upb then
for vpb=1,tpb-upb do
local wpb=Bob[((vpb-1)%upb)+1]
table.insert(Bob,table.clone(wpb))
end
else
for xpb=1,upb-tpb do
table.remove(Bob)
end
end
end
return Bob,fb.waveYen(yob,zob)
