end
local Asb,Bsb={},{}
for Csb,Dsb in pairs(P.simCal)do
local Esb=Csb~=sAd[1748]and not tostring(Csb):find(sAd[3093],1,true)and type(Dsb)==sAd[1723]and type(Dsb.dmgK)==sAd[1723]and Dsb.dmgK or nil
