fb.DMG_SOLVE_LO,fb.DMG_SOLVE_HI,fb.DMG_SOLVE_TRIES=0.1,3,6
function fb.dmgSolve(ctb,dtb,etb,ftb,gtb)
local function htb(itb)
local jtb=table.clone(ctb)
jtb.dmgMul,jtb._dk=itb,nil
local ktb,ltb=pcall(fb.runRaw,jtb,dtb,etb)
if not(ktb and type(ltb)==sAd[1723])then
return nil
end
if gtb then
return ltb.won and 1 or-1
end
if ltb.won then
return 1
end
return(tonumber(ltb.wave)or 0)-ftb
end
local mtb,ntb=math.log(fb.DMG_SOLVE_LO),math.log(fb.DMG_SOLVE_HI)
local otb=htb(fb.DMG_SOLVE_LO)
if not otb then
return nil
end
if otb>=0 then
return fb.DMG_SOLVE_LO
end
local ptb=htb(fb.DMG_SOLVE_HI)
if not ptb then
return nil
end
if ptb<0 then
return fb.DMG_SOLVE_HI
end
for qtb=1,fb.DMG_SOLVE_TRIES do
task.wait()
local rtb=(mtb+ntb)/2
local stb=htb(math.exp(rtb))
if not stb then
return nil
end
if stb>=0 then
ntb=rtb
else
mtb=rtb
end
end
return math.exp(ntb)
end
