local function Xtb(Ytb)
local Ztb=Ntb[tostring(Ytb)]
if type(Ztb)==sAd[1723]and(tonumber(Ztb.n)or 0)>0 then
return tonumber(Ztb.n)
end
local _tb,aub=0,math.huge
for bub=1,#fb.DMG_BANDS do
local cub=Ntb[tostring(bub)]
if type(cub)==sAd[1723]and tonumber(cub.k)and(tonumber(cub.n)or 0)>0 and math.abs(bub-Ytb)<aub then
_tb,aub=tonumber(cub.n),math.abs(bub-Ytb)
