local dub=fb.dmgBand(math.max(1,Etb))
local eub={}
for fub=1,dub do
eub[fub]=Xtb(fub)
end
local gub={}
local hub=Dtb^(1-fb.UNIT_SPLIT)
for iub=1,dub do
local jub=iub==1 and 1 or fb.DMG_BANDS[iub-1]+1
local kub=type(Ntb[tostring(iub)])==sAd[1723]and Ntb[tostring(iub)]or nil
