if type(TSb)==sAd[1723]then
USb=TSb.id or TSb.item_id or TSb.item
VSb=tonumber(TSb.cost)or tonumber(TSb.price)
elseif type(TSb)==sAd[634]then
USb=TSb
elseif ib.item(SSb)then
USb=SSb
VSb=tonumber(TSb)
end
if type(USb)==sAd[634]and ib.item(USb)then
table.insert(RSb,{key=SSb,id=USb,cost=VSb or tonumber(ib.item(USb).cost)or 0,bought=type(TSb)==sAd[1723]and(TSb.bought or TSb.sold or TSb.purchased)or nil})
end
end
if#RSb==0 and not QSb then
for WSb,XSb in pairs(PSb)do
if type(XSb)==sAd[1723]then
RSb=ib.offers(XSb,true)
if#RSb>0 then
break
end
end
end
end
return RSb
end
function ib.buy(YSb)
