function ib.shopAhead(fTb)
for gTb,hTb in ipairs(ib.rooms(fTb))do
if hTb.tags[ib.T.SHOP]then
return true
end
for iTb,jTb in ipairs(ib.after(fTb,hTb.choice))do
if jTb.tags[ib.T.SHOP]then
return true
end
end
end
return false
end
ib.LUCK_RESERVE=500
ib.MIN_WORTH=0.02
ib.TOP_WORTH=0.08
function ib.shop(kTb,lTb)
local mTb=ib.cleared(kTb)
local nTb=ib.res(kTb)
local oTb=1+0.1*(ib.items(kTb)._curse_shop or 0)
local pTb=ib.shopAhead(kTb)and math.ceil(ib.LUCK_RESERVE*oTb)or 0
local qTb={}
local rTb,sTb={},0
for tTb,uTb in ipairs(ib.offers(lTb and lTb.data))do
uTb.cost=math.ceil(uTb.cost*oTb)
table.insert(rTb,tostring(ib.item(uTb.id).name or uTb.id))
if not uTb.bought and not ib.isCurse(uTb.id)then
uTb.luck=tonumber(ib.item(uTb.id).luck_increase)~=nil
uTb.v=ib.itemValue(uTb.id,kTb)
if not uTb.luck and uTb.v/math.max(1,uTb.cost)<ib.MIN_WORTH then
sTb=sTb+1
elseif uTb.v>0 and(uTb.luck or mTb>=10 or uTb.v/math.max(1,uTb.cost)>=ib.TOP_WORTH)then
table.insert(qTb,uTb)
end
end
end
table.sort(qTb,function(vTb,wTb)
if vTb.luck~=wTb.luck then
return vTb.luck
end
return vTb.v/math.max(1,vTb.cost)>wTb.v/math.max(1,wTb.cost)
end)
local xTb,yTb,zTb={},0,0
for ATb,BTb in ipairs(qTb)do
if BTb.cost<=nTb-(BTb.luck and 0 or pTb)then
if ib.buy(BTb)then
nTb=ib.res(ib.data())
table.insert(xTb,string.format(sAd[3328],tostring(ib.item(BTb.id).name or BTb.id),BTb.cost))
end
elseif BTb.cost<=nTb then
zTb=zTb+1
else
yTb=yTb+1
end
end
ib.note(string.format(sAd[3329],mTb,#rTb>0 and table.concat(rTb,sAd[1834])or sAd[3330],#xTb>0 and(sAd[3331]..table.concat(xTb,sAd[1834]))or(mTb<10 and sAd[3332]or(zTb>0 and sAd[3333]or sAd[3334])),nTb,yTb>0 and string.format(sAd[3335],yTb)or sAd[648],zTb>0 and string.format(sAd[3336],zTb,pTb)or sAd[648],sTb>0 and string.format(sAd[3337],sTb)or sAd[648]))
F.request(sAd[3338],sAd[3339])
end
function ib.shrine(CTb,DTb)
