local HTb
for ITb,JTb in ipairs(ETb)do
local KTb=ib.item(JTb.id)
table.insert(GTb,tostring(KTb and KTb.name or JTb.id))
if ib.isCurse(JTb.id)then
local LTb,MTb,NTb=pcall(ib.curseOk,JTb.id,CTb,ib.cleared(CTb)+1,nil,ib.rooms(CTb))
if LTb and not MTb then
HTb=NTb
end
else
