end
ib.note(string.format(sAd[3342],#GTb>0 and table.concat(GTb,sAd[1834])or sAd[3330],OTb and sAd[3343]or(HTb and(sAd[3344]..HTb)or sAd[3345])))
end
function ib.wallet()
local PTb=N.session()and N.session().profile_data or{}
local QTb=PTb.inventory or{}
local RTb={gems=tonumber(N.cur(sAd[1786]))or 0,gold=tonumber(N.cur(sAd[1788]))or 0,items={},units={},unique=0}
for STb,TTb in pairs(QTb.normal_items or{})do
RTb.items[STb]=tonumber(TTb)or 0
end
for UTb,VTb in pairs(PTb.collection and PTb.collection.owned_units or{})do
RTb.units[UTb]=VTb.unit_id
end
for WTb in pairs(QTb.unique_items or{})do
RTb.unique=RTb.unique+1
end
return RTb
end
function ib.walletDiff(XTb,YTb)
local ZTb={}
if YTb.gems~=XTb.gems then
table.insert(ZTb,string.format(sAd[3346],YTb.gems-XTb.gems))
end
if YTb.gold~=XTb.gold then
table.insert(ZTb,string.format(sAd[3347],YTb.gold-XTb.gold))
end
for _Tb,aUb in pairs(YTb.items)do
if aUb~=(XTb.items[_Tb]or 0)then
table.insert(ZTb,string.format(sAd[3348],aUb-(XTb.items[_Tb]or 0),tostring(_Tb)))
end
end
for bUb,cUb in pairs(YTb.units)do
if not XTb.units[bUb]then
table.insert(ZTb,sAd[3349]..V.name(cUb))
end
end
if YTb.unique~=XTb.unique then
table.insert(ZTb,string.format(sAd[3350],YTb.unique-XTb.unique))
end
return#ZTb>0 and table.concat(ZTb,sAd[1834])or sAd[3351]
end
function ib.openChests(dUb,eUb)
local fUb,gUb,hUb=ib.res(dUb)
local iUb=ib.lives(dUb)
local jUb=ib.cleared(dUb)
if not(eUb or jUb>=ib.ROOMS or iUb<=1)then
ib.note(string.format(sAd[3352],jUb,gUb,hUb,ib.luck(dUb)))
F.request(sAd[3338],sAd[3339])
return
end
local kUb,lUb,mUb=0,0,0
local nUb=tonumber(N.cur(sAd[1786]))or 0
local oUb=ib.wallet()
for pUb=1,gUb+hUb+4 do
local qUb,rUb,sUb=ib.res(ib.data())
if rUb+sUb<=0 or mUb>=2 then
break
end
local tUb,uUb
if rUb>0 then
tUb,uUb=F.request(sAd[3353],sAd[3354])
else
tUb,uUb=F.request(sAd[3353],sAd[3354],true)
end
if tUb and uUb~=nil then
F.log(1,sAd[3322],sAd[3355]..(type(uUb)==sAd[1723]and U.json(U.plain(uUb)):sub(1,300)or tostring(uUb)))
end
local vUb=U.now()
while U.now()-vUb<4 do
local wUb,xUb,yUb=ib.res(ib.data())
if xUb<rUb or yUb<sUb then
break
end
task.wait(0.25)
end
local zUb,AUb,BUb=ib.res(ib.data())
if AUb<rUb then
kUb=kUb+(rUb-AUb)
mUb=0
elseif BUb<sUb then
lUb=lUb+(sUb-BUb)
mUb=0
else
mUb=mUb+1
end
task.wait(1)
if AUb<rUb or BUb<sUb then
local CUb=ib.wallet()
local DUb=ib.walletDiff(oUb,CUb)
F.log(1,sAd[3322],(BUb<sUb and sAd[3356]or sAd[3355])..DUb)
P.dg.pay=P.dg.pay or{}
local EUb={}
for FUb,GUb in pairs(CUb.items)do
if GUb~=(oUb.items[FUb]or 0)then
EUb[FUb]=GUb-(oUb.items[FUb]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=BUb<sUb,gems=CUb.gems-oUb.gems,luck=ib.luck(dUb),paid=DUb,items=EUb})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
oUb=CUb
end
end
ib.note(string.format(sAd[3357],kUb,lUb,eUb and sAd[3358]or(iUb<=1 and sAd[3359]or sAd[3360]),ib.luck(dUb),(tonumber(N.cur(sAd[1786]))or 0)-nUb))
local HUb,IUb,JUb=ib.res(ib.data())
if(eUb or jUb>=ib.ROOMS)and IUb+JUb>0 then
ib.note(string.format(sAd[3361],IUb,JUb))
W.rec(sAd[2162]).restUntil=os.time()+1800
return sAd[3362]
end
if not eUb then
F.request(sAd[3338],sAd[3339])
end
end
