local Cdc=math.min(49,math.floor(zdc.prog*50))
if Cdc<25 then
tdc=bit32 .bor(tdc,bit32 .lshift(1,Cdc))
else
udc=bit32 .bor(udc,bit32 .lshift(1,Cdc-25))
end
if zdc.prog<=0.3 then
wdc=wdc+1
elseif zdc.prog>=0.7 then
xdc=xdc+1
end
end
end
if vdc>0 then
local Ddc=tdc..sAd[1849]..udc
