end
local function Eec(Fec)
local Gec=0
for Hec,Iec in pairs(Fec)do
local Jec=bb.spotRec(Hec,Iec)
if Jec then
Gec=Gec+(tonumber(Jec.wins)or 0)*200-((tonumber(Jec.runs)or 0)-(tonumber(Jec.wins)or 0))*1500
end
end
return Gec
end
local function Kec(Lec)
local Mec,Nec,Oec=0,0,0
for Pec,Qec in ipairs(lec)do
local Rec=os.clock()
local Sec=fb.runRaw(gec,hec,{hpMul=Qec,layout=Cec(Lec),bg=true})
Mec,Nec,Oec=Mec+fb.objective(Sec),Nec+(tonumber(Sec.kills)or 0),Oec+(tonumber(Sec.wave)or 0)
task.wait(math.clamp((os.clock()-Rec)*3,0.25,1.5))
if not fec()then
return nil
end
end
nec.n,nec.run=nec.n+1,nec.run+1
return Mec/ #lec*100+Eec(Lec),Nec/ #lec,Oec/ #lec
end
local function Tec(Uec)
