F.log(1,sAd[2196],bb.studyWords(nec))
end
end
local jfc={dfc}
for kfc,lfc in ipairs(dec.attackers)do
local mfc={}
for nfc,ofc in ipairs(jfc)do
table.insert(mfc,ofc)
for pfc,qfc in ipairs(oec[lfc.id]or{})do
