local Hfc,Ifc,Jfc=Kec(Cfc)
if not Hfc then
break
end
gfc({spots=Cfc,s=Hfc,kills=Ifc,wave=Jfc})
ifc()
end
bb.studyEnd(nec,dec,dfc)
end
