function bb.holdGain(Roc,Soc)
if bb.random or not Soc or not bb.info then
return 0
end
local Toc=V.attackInfo(Soc.atk,Soc.range)
if(Toc.stun or 0)<=0 and(Toc.slowTime or 0)<=0 then
return 0
end
local Uoc=0
for Voc,Woc in ipairs(bb.mine or{})do
local Xoc=Woc._stats
local Yoc=V.rows(Xoc.id.Value)
local Zoc=Yoc and Yoc[math.min(Xoc.upgrade.Value,Yoc.max)]
local _oc=Zoc and Zoc.atk and V.attackInfo(Zoc.atk,Zoc.range)
if _oc and((_oc.stun or 0)>0 or(_oc.slowTime or 0)>0)then
Uoc=Uoc+1
end
end
local apc,bpc=fb.mask(bb.info.map,V.range(Roc.u,0)*(bb.info.rangeScale or 1)),0
for cpc=1,fb.BINS do
if apc[cpc]then
bpc=bpc+1
end
end
local dpc=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local epc=(V.airFrom(Roc.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(Toc,bb.teamDps or 0,bpc/(math.max(0.1,dpc)*fb.BINS)*epc,Uoc)
end
function bb.buffGain(fpc)
local gpc=V.allyBuff(fpc.id)
if not gpc then
return 0
end
local hpc=bb.buffShort(gpc)
local ipc=P.stack[gpc.attack]
local jpc=ipc and ipc.stacks and(ipc.cap or 1)or nil
local kpc,lpc=pcall(V.range,fpc.u,0)
lpc=(kpc and tonumber(lpc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local mpc=jpc and O.community and tonumber(gpc.time)and tonumber(gpc.cd)
local function npc(opc,ppc)
local qpc=math.floor(opc*gpc.time/math.max(1,gpc.cd)+0.001)
return math.min(jpc,(1+ppc)^qpc-1)
end
local rpc=0
for spc,tpc in ipairs(hpc)do
local upc=0
for vpc,wpc in ipairs(hpc)do
if(wpc.pos-tpc.pos).Magnitude<=lpc then
local xpc=gpc.types[wpc.base]
