function bb.learn()
local axc=bb.calRun and bb.calRun.potBy
if type(axc)~=sAd[1723]then
return
end
pcall(bb.sampleHelpers,true)
local bxc={}
for cxc,dxc in pairs(bb.ownDealt or{})do
if not V.isFarm(dxc.id)then
bxc[dxc.id]=(bxc[dxc.id]or 0)+(tonumber(dxc.v)or 0)
end
end
for exc,fxc in pairs(bb.helperDealt or{})do
if fxc.owner and V.SUMMONER[fxc.owner]then
bxc[fxc.owner]=(bxc[fxc.owner]or 0)+(tonumber(fxc.v)or 0)
end
end
local gxc,hxc=0,0
for ixc,jxc in pairs(axc)do
if jxc>0 then
gxc=gxc+(bxc[ixc]or 0)
hxc=hxc+jxc
end
end
if gxc<=0 or hxc<=0 then
return
end
local kxc=gxc/hxc
bb.lastEff={}
for lxc,mxc in pairs(axc)do
if mxc>0 and mxc/hxc>0.02 then
local nxc=P.learn[lxc]or{eff=1,n=0,v=3}
if(tonumber(nxc.v)or 0)<3 then
nxc.eff,nxc.v=(tonumber(nxc.eff)or 1)*V.effRescale(lxc),3
end
local oxc=math.max(0.02,0.25*math.sqrt(30/(30+nxc.n)))
local pxc=U.clamp(((bxc[lxc]or 0)/mxc)/kxc,0.2,6)
bb.lastEff[lxc]=math.floor(pxc*1000+0.5)/1000
nxc.eff=nxc.eff+(pxc-nxc.eff)*oxc
nxc.n=nxc.n+1
P.learn[lxc]=nxc
end
end
local qxc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if qxc and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==sAd[1723]and P.mapLearn or{}
local rxc=type(P.mapLearn[qxc])==sAd[1723]and P.mapLearn[qxc]or{}
for sxc,txc in pairs(bb.lastEff)do
local uxc=type(rxc[sxc])==sAd[1723]and rxc[sxc]or{eff=txc,n=0}
local vxc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(uxc.n)or 0))))
uxc.eff=(tonumber(uxc.n)or 0)==0 and txc or((tonumber(uxc.eff)or txc)+(txc-(tonumber(uxc.eff)or txc))*vxc)
uxc.n=(tonumber(uxc.n)or 0)+1
rxc[sxc]=uxc
end
rxc._at=os.time()
P.mapLearn[qxc]=rxc
if U.count(P.mapLearn)>80 then
local wxc,xxc
for yxc,zxc in pairs(P.mapLearn)do
if not xxc or(tonumber(zxc._at)or 0)<xxc then
wxc,xxc=yxc,tonumber(zxc._at)or 0
end
end
P.mapLearn[wxc]=nil
end
end
end
