bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(eDc,fDc)
local gDc=(fDc.t or 0)-(eDc.t or 0)
if gDc<bb.BASE_WIN-1 then
return false
end
local hDc=((tonumber(eDc.base)or 0)-(tonumber(fDc.base)or 0))/gDc
if hDc<=0 or(tonumber(fDc.base)or 0)<=0 then
return false
end
local iDc=fDc.base/hDc
local jDc,kDc=0,0
local lDc,mDc=eDc.foes or{},fDc.foes or{}
for nDc,oDc in pairs(mDc)do
if oDc.prog>=bb.BASE_END then
jDc=jDc+oDc.hp
local pDc=lDc[nDc]
if pDc then
kDc=kDc+math.max(0,pDc.hp-oDc.hp)
end
end
end
for qDc,rDc in pairs(lDc)do
if rDc.prog>=bb.BASE_END and not mDc[qDc]then
kDc=kDc+rDc.hp
end
end
if jDc<=0 then
return false
end
local sDc=kDc/gDc
local tDc=sDc>0 and jDc/sDc or math.huge
local uDc={baseTime=iDc,loss=hDc,atEnd=jDc,rate=sDc,killTime=tDc}
return iDc<bb.BASE_SOON and tDc>iDc*bb.BASE_MARGIN,uDc
end
