Nfd=Nfd+1
end
end
for Sfd,Tfd in ipairs(Lfd.items or{})do
if not Ofd[Tfd.id]then
Mfd=Mfd+1
Nfd=Nfd+1
end
end
return Nfd>0 and Mfd/Nfd or 0
end
